from fractions import Fraction

from .money import MAX_AMOUNT, _check_cents_amount, _cents_to_decimal, _to_exact_fraction, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    total_cents = 0
    for item in amounts:
        fraction = _to_exact_fraction(item)
        total_cents += _check_cents_amount(fraction)
    if Fraction(total_cents, 100) > MAX_AMOUNT:
        raise ValueError("total exceeds 1000000.00")
    total = _cents_to_decimal(total_cents)
    return {"total": format_amount(total), "count": len(amounts)}

